-- #1653 Evitar duplicats de codi de usuari majuscules/minuscules
-- Postgres no suporta ON UPDATE CASCADE ni DISABLE CONSTRAINT per nom;
-- s'usa session_replication_role per desactivar els triggers de FK durant la migració.

SET session_replication_role = replica;

